class Solution {
    public int closestToTarget(int[] arr,int target){
        Set<Integer> previous=new HashSet<>();
        int answer=Integer.MAX_VALUE;
        for(int value:arr){
            Set<Integer> current=new HashSet<>();
            current.add(value);
            for(int old:previous)current.add(old&value);
            for(int result:current)answer=Math.min(answer,Math.abs(result-target));
            previous=current;
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun closestToTarget(arr:IntArray,target:Int):Int{
        var previous=emptySet<Int>();
        var answer=Int.MAX_VALUE;
        for(value in arr){
            val current=mutableSetOf(value);
            for(old in previous)current.add(old and value);
            for(result in current)answer=minOf(answer,kotlin.math.abs(result-target));
            previous=current
        };
        return answer
    }
}

code.cpp:
class Solution {
    public: int closestToTarget(vector<int>& arr,int target){
        unordered_set<int> previous;
        int answer=INT_MAX;
        for(int value:arr){
            unordered_set<int> current{
                value
            };
            for(int old:previous)current.insert(old&value);
            for(int result:current)answer=min(answer,abs(result-target));
            previous=move(current);
        }
        return answer;
    }
};
